use semio_plugin_interpreter::*;
use semio_framework_job::{Generation,OperationId,OriginalJobFixtureCaller,StepContext};
use semio_framework_test_fixtures::fixture_text;
use semio_framework_value::{RetainedCloneGrant,ValueError};
use std::sync::Arc;
use std::sync::atomic::{AtomicU64,Ordering};
static NOW:AtomicU64=AtomicU64::new(1000);
fn clock()->Option<u64>{Some(NOW.load(Ordering::Acquire))}
fn binary()->Vec<u8>{let mut bytes=b"\0asm\x01\0\0\0".to_vec();for(id,section)in [(4,vec![1,0x70,0,3]),(5,vec![1,0,1]),(6,vec![1,0x7f,0,0x41,7,0x0b]),(7,vec![3,6,b'm',b'e',b'm',b'o',b'r',b'y',2,0,5,b't',b'a',b'b',b'l',b'e',1,0,5,b'v',b'a',b'l',b'u',b'e',3,0]),(11,vec![1,0,0x41,5,0x0b,2,b'2',b'0'])]{bytes.extend([id,section.len()as u8]);bytes.extend(section)}bytes}
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:10000,maximum_copy_bytes:2_000_000,maximum_capacity_bytes:2_000_000,maximum_release_bytes:2_000_000,maximum_depth:64}}
fn oracle(bytes:&[u8])->(wasmtime::Store<()>,wasmtime::Instance){let engine=wasmtime::Engine::default();let module=wasmtime::Module::new(&engine,bytes).unwrap();let mut store=wasmtime::Store::new(&engine,());let instance=wasmtime::Instance::new(&mut store,&module,&[]).unwrap();(store,instance)}
fn observed<T>(run:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);(value,(heap.requested_bytes,heap.released_bytes))}
fn scalar_input(cx:&StepContext<'_>)->Result<semio_framework_actor::RetainedTurnInput,ValueError>{
 use semio_framework_actor::RetainedTurnInput;
 Ok(RetainedTurnInput{grant:cx.retained_grant(),..RetainedTurnInput::borrow_original(cx)?})
}
fn observed_turn<T>(caller:&mut OriginalJobFixtureCaller,epoch:&mut u64,grant:RetainedCloneGrant,run:impl FnOnce(&mut semio_framework_job::StepContext<'_>)->Result<T,semio_framework_job::OriginalTurnFailure>)->(T,(usize,usize)){*epoch+=1;observed(||caller.turn(grant,|cx|{cx.bind_original_source_epoch(*epoch)?;run(cx)}).unwrap())}

fn scalar_binary()->Vec<u8>{let mut bytes=b"\0asm\x01\0\0\0".to_vec();let mut leb=Vec::new();let mut value=(2u64<<32)|5;loop{let byte=(value&127)as u8;value>>=7;let done=value==0&&byte&64==0;leb.push(byte|if done{0}else{128});if done{break}}let mut body=vec![0,0x42];body.extend(leb);body.push(0x0b);let mut code=vec![1,body.len()as u8];code.extend(body);for(id,section)in[(1,vec![1,0x60,0,1,0x7e]),(3,vec![1,0]),(5,vec![1,0,1]),(7,vec![2,6,b'm',b'e',b'm',b'o',b'r',b'y',2,0,7,b'v',b'e',b'r',b's',b'i',b'o',b'n',0,0]),(10,code),(11,vec![1,0,0x41,5,0x0b,2,b'2',b'0'])]{bytes.extend([id,section.len()as u8]);bytes.extend(section)}bytes}
#[test]
fn original_core_scalar_startup_measures_execution_without_replacing_original_currency(){
 NOW.store(1000,Ordering::Release);let bytes=scalar_binary();let module=Arc::new(CoreModule::parse(&bytes).unwrap());let(mut store,instance)=oracle(&bytes);let expected=instance.get_typed_func::<(),i64>(&mut store,"version").unwrap().call(&mut store,()).unwrap();let stock=grant();let mut caller=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock,clock,100000,100000);let mut epoch=1;let mut owner=caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;CoreInstanceOpening::begin(&module,cx)}).unwrap().unwrap();let mut born=0;let phased=RetainedCloneGrant{maximum_copy_bytes:1024,..stock};while !owner.resources_ready(){let(_,heap)=observed_turn(&mut caller,&mut epoch,phased,|cx|{owner.advance(&module,cx)});born+=heap.0;assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap)}let function=match module.export("version").unwrap(){ExportKind::Function(function)=>*function,_=>panic!()};let(ready,heap)=observed_turn(&mut caller,&mut epoch,stock,|cx|{owner.begin_function_step(&module,function,&[],cx)});assert!(ready);assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;
 let mut measured=0;let mut released=0;let mut physical_only=0;let mut complete=false;for _ in 0..40{let(call,heap)=observed_turn(&mut caller,&mut epoch,phased,|cx|{let execution=semio_framework_actor::OriginalGuestExecutionBudget{input:scalar_input(cx)?,fuel:1,deadline_us:cx.deadline_us()};let wrong=semio_framework_actor::OriginalGuestExecutionBudget{input:semio_framework_actor::RetainedTurnInput{generation:4,..execution.input},..execution};assert!(owner.advance_scalar(&module,wrong,cx).is_err());owner.advance_scalar(&module,execution,cx)});assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;released+=heap.1;let instructions=call.execution.spent_fuel.unwrap();assert!(instructions<=1);measured+=instructions;if instructions==0{physical_only+=1}match call.result.unwrap(){CoreOriginalInvocationStatus::Complete=>{complete=true;assert_eq!(owner.invocation_values().unwrap(),&[Value::I64(expected)]);break},CoreOriginalInvocationStatus::Pending=>assert!(owner.invocation_values().is_none()),status=>panic!("{status:?}")}}
 assert!(complete);assert_eq!(measured,2);assert!(physical_only>0);caller.cancel().cancel_now();for _ in 0..80{if owner.terminal_is_empty(){break}let(_,heap)=observed_turn(&mut caller,&mut epoch,stock,|cx|{owner.close_step(&module,cx)});released+=heap.1;assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap)}assert!(owner.terminal_is_empty());assert_eq!(born,released);assert_eq!(observed(||drop(owner)).1,(0,0));caller.retire(stock);
}
#[test]
fn original_core_input_memory_copy_preserves_denied_cursor_and_matches_wasmtime(){
 NOW.store(1000,Ordering::Release);let bytes=binary();let module=Arc::new(CoreModule::parse(&bytes).unwrap());let(mut store,instance)=oracle(&bytes);let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../../../🏗️instance/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let source=fixture["inputCopy"]["source"].as_str().unwrap().as_bytes();assert_eq!(size_of::<usize>(),fixture["inputCopy"]["cursorBytes"].as_u64().unwrap()as usize);instance.get_memory(&mut store,"memory").unwrap().write(&mut store,100,source).unwrap();let expected=instance.get_memory(&mut store,"memory").unwrap().data(&store).to_vec();let stock=grant();let mut caller=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock,clock,100000,100000);let mut epoch=1;let mut owner=caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;CoreInstanceOpening::begin(&module,cx)}).unwrap().unwrap();let mut born=0;while !owner.resources_ready(){let(_,heap)=observed_turn(&mut caller,&mut epoch,stock,|cx|{owner.advance(&module,cx)});assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;}let mut copied=0;let(done,heap)=observed_turn(&mut caller,&mut epoch,RetainedCloneGrant{maximum_copy_bytes:size_of::<usize>()-1,..stock},|cx|{owner.write_original_memory_step(&module,0,100,source,&mut copied,cx)});assert!(!done);assert_eq!(heap,(0,0));assert_eq!(copied,0);assert_eq!(caller.receipt(),Default::default());let mut phases=0;while copied<source.len(){let(_,heap)=observed_turn(&mut caller,&mut epoch,RetainedCloneGrant{maximum_copy_bytes:32,..stock},|cx|{owner.write_original_memory_step(&module,0,100,source,&mut copied,cx)});assert_eq!(heap,(0,0));assert!(caller.receipt().copied_bytes<=32);phases+=1;assert!(phases<4)}assert_eq!(owner.resources().unwrap().memory(0).unwrap(),expected);let mut released=0;for _ in 0..80{if owner.terminal_is_empty(){break}let(_,heap)=observed_turn(&mut caller,&mut epoch,stock,|cx|{owner.close_step(&module,cx)});assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);released+=heap.1;}assert!(owner.terminal_is_empty());assert_eq!(born,released);assert_eq!(observed(||drop(owner)).1,(0,0));caller.retire(stock);
}
#[test]
fn original_core_nested_call_pays_each_frame_and_preserves_denied_operands(){
 NOW.store(1000,Ordering::Release);let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../../../🏗️instance/▶️invocation/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let bytes:Vec<u8>=fixture["moduleHex"].as_str().unwrap().as_bytes().chunks_exact(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect();let module=Arc::new(CoreModule::parse(&bytes).unwrap());let(mut store,instance)=oracle(&bytes);let expected=instance.get_typed_func::<(),i64>(&mut store,"invoke").unwrap().call(&mut store,()).unwrap();assert_eq!(expected,fixture["expected"].as_i64().unwrap());let stock=grant();let mut caller=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock,clock,100000,100000);let mut epoch=1;let mut owner=caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;CoreInstanceOpening::begin(&module,cx)}).unwrap().unwrap();let mut born=0;let mut released=0;while !owner.resources_ready(){let(_,heap)=observed_turn(&mut caller,&mut epoch,stock,|cx|{owner.advance(&module,cx)});assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;released+=heap.1;}let(ready,heap)=observed_turn(&mut caller,&mut epoch,stock,|cx|{owner.begin_function_step(&module,0,&[],cx)});assert!(ready);assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;let mut vm=0;
 for _ in 0..2{let(call,heap)=observed_turn(&mut caller,&mut epoch,stock,|cx|{owner.advance_scalar(&module,semio_framework_actor::OriginalGuestExecutionBudget{input:scalar_input(cx)?,fuel:1,deadline_us:cx.deadline_us()},cx)});assert_eq!(call.result.unwrap(),CoreOriginalInvocationStatus::Pending);vm+=call.execution.spent_fuel.unwrap();assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;released+=heap.1;}let before=owner.resources().unwrap().testkit_stack_site().unwrap();let(call,heap)=observed_turn(&mut caller,&mut epoch,RetainedCloneGrant{maximum_capacity_bytes:0,..stock},|cx|{owner.advance_scalar(&module,semio_framework_actor::OriginalGuestExecutionBudget{input:scalar_input(cx)?,fuel:1,deadline_us:cx.deadline_us()},cx)});assert_eq!(call.result.unwrap(),CoreOriginalInvocationStatus::Pending);assert_eq!(call.execution.spent_fuel,Some(0));assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),Default::default());assert_eq!(owner.resources().unwrap().testkit_stack_site().unwrap(),before);let mut physical_only=0;for _ in 0..100{let(call,heap)=observed_turn(&mut caller,&mut epoch,stock,|cx|{owner.advance_scalar(&module,semio_framework_actor::OriginalGuestExecutionBudget{input:scalar_input(cx)?,fuel:1,deadline_us:cx.deadline_us()},cx)});assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;released+=heap.1;let instructions=call.execution.spent_fuel.unwrap();vm+=instructions;if instructions==0{physical_only+=1;}if call.result.unwrap()==CoreOriginalInvocationStatus::Complete{break}}assert_eq!(owner.invocation_values().unwrap(),&[Value::I64(expected)]);assert_eq!(vm,fixture["expectedInstructions"].as_u64().unwrap());assert!(physical_only>0);caller.cancel().cancel_now();for _ in 0..100{if owner.terminal_is_empty(){break}let(_,heap)=observed_turn(&mut caller,&mut epoch,stock,|cx|{owner.close_step(&module,cx)});assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);released+=heap.1;}assert!(owner.terminal_is_empty());assert_eq!(born,released);assert_eq!(observed(||drop(owner)).1,(0,0));caller.retire(stock);
}

#[test]
fn original_core_memory_instruction_preserves_denied_store_and_matches_wasmtime(){
 NOW.store(1000,Ordering::Release);let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../../../🏗️instance/▶️invocation/📥️memory/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let bytes:Vec<u8>=fixture["moduleHex"].as_str().unwrap().as_bytes().chunks_exact(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect();let module=Arc::new(CoreModule::parse(&bytes).unwrap());let(mut store,instance)=oracle(&bytes);let expected=instance.get_typed_func::<(),i64>(&mut store,"invoke").unwrap().call(&mut store,()).unwrap();assert_eq!(expected,fixture["expected"].as_i64().unwrap());let address=fixture["address"].as_u64().unwrap()as usize;let width=fixture["width"].as_u64().unwrap()as usize;let expected_bytes=instance.get_memory(&mut store,"memory").unwrap().data(&store)[address..address+width].to_vec();let stock=grant();let mut caller=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock,clock,100000,100000);let mut epoch=1;let mut owner=caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;CoreInstanceOpening::begin(&module,cx)}).unwrap().unwrap();let mut born=0;let mut released=0;while !owner.resources_ready(){let(_,heap)=observed_turn(&mut caller,&mut epoch,RetainedCloneGrant{maximum_copy_bytes:1024,..stock},|cx|{owner.advance(&module,cx)});assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;released+=heap.1;}let(ready,heap)=observed_turn(&mut caller,&mut epoch,stock,|cx|{owner.begin_function_step(&module,0,&[],cx)});assert!(ready);assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;let mut vm=0;
 for _ in 0..2{let(call,heap)=observed_turn(&mut caller,&mut epoch,stock,|cx|{owner.advance_scalar(&module,semio_framework_actor::OriginalGuestExecutionBudget{input:scalar_input(cx)?,fuel:1,deadline_us:cx.deadline_us()},cx)});assert_eq!(call.result.unwrap(),CoreOriginalInvocationStatus::Pending);vm+=call.execution.spent_fuel.unwrap();assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;released+=heap.1;}let before=owner.resources().unwrap().testkit_stack_site().unwrap();let memory=owner.resources().unwrap().memory(0).unwrap();let original_memory_pointer=memory.as_ptr();assert_eq!(&memory[address..address+width],&[0;8]);let(call,heap)=observed_turn(&mut caller,&mut epoch,stock,|cx|{owner.advance_scalar(&module,semio_framework_actor::OriginalGuestExecutionBudget{input:scalar_input(cx)?,fuel:fixture["deniedFuel"].as_u64().unwrap(),deadline_us:cx.deadline_us()},cx)});assert_eq!(call.result.unwrap(),CoreOriginalInvocationStatus::Pending);assert_eq!(call.execution.spent_fuel,Some(0));assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),Default::default());assert_eq!(owner.resources().unwrap().testkit_stack_site().unwrap(),before);assert_eq!(&owner.resources().unwrap().memory(0).unwrap()[address..address+width],&[0;8]);for _ in 0..20{let(call,heap)=observed_turn(&mut caller,&mut epoch,stock,|cx|{owner.advance_scalar(&module,semio_framework_actor::OriginalGuestExecutionBudget{input:scalar_input(cx)?,fuel:1,deadline_us:cx.deadline_us()},cx)});assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;released+=heap.1;vm+=call.execution.spent_fuel.unwrap();if call.result.unwrap()==CoreOriginalInvocationStatus::Complete{break}}assert_eq!(owner.invocation_values().unwrap(),&[Value::I64(expected)]);assert_eq!(vm,fixture["expectedInstructions"].as_u64().unwrap());let memory=owner.resources().unwrap().memory(0).unwrap();assert_eq!(memory.as_ptr(),original_memory_pointer);assert_eq!(&memory[address..address+width],expected_bytes.as_slice());caller.cancel().cancel_now();for _ in 0..100{if owner.terminal_is_empty(){break}let(_,heap)=observed_turn(&mut caller,&mut epoch,stock,|cx|{owner.close_step(&module,cx)});assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);released+=heap.1;}assert!(owner.terminal_is_empty());assert_eq!(born,released);assert_eq!(observed(||drop(owner)).1,(0,0));caller.retire(stock);
}

